#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, V;
    if (cin >> n >> V) {
        vector<int> dp(V + 1, 0);
        for (int i = 0; i < n; ++i) {
            int v, w;
            cin >> v >> w;
            // 01背包必须逆序遍历容量
            for (int j = V; j >= v; --j) {
                dp[j] = max(dp[j], dp[j - v] + w);
            }
        }
        cout << dp[V] << "\n";
    }
    return 0;
}
